    $create('identity_tenant', static function (Blueprint $t): void { $t->id(); $t->char('public_id',36)->unique(); $t->string('code',64)->unique(); $t->string('name',100); $t->smallInteger('status')->default(1); $t->timestamps(); $t->softDeletes(); });
