    $create('identity_audit_log', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('user_id')->nullable(); $t->bigInteger('client_id')->nullable(); $t->string('event_type',64); $t->enum('outcome',['success','failure']); $t->char('subject_hash',64)->nullable(); $t->char('ip_hash',64)->nullable(); $t->json('context')->nullable(); $t->timestamps(); $t->index(['tenant_id','event_type','created_at']); });
