    foreach (['application_role_permission' => ['role_id','permission_id'], 'application_user_permission' => ['user_id','permission_id'], 'application_user_role' => ['user_id','role_id']] as $name => $columns) $create($name, static function (Blueprint $t) use ($columns): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('application_id'); foreach ($columns as $column) $t->bigInteger($column); $t->timestamps(); $t->unique(array_merge(['tenant_id','application_id'],$columns)); });
    $create('oauth_client', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('application_id'); $t->string('client_id',128)->unique(); $t->string('name',100); $t->enum('client_type',['public','confidential','machine']); $t->enum('token_endpoint_auth_method',['none','client_secret_basic']); $t->smallInteger('require_pkce')->default(0); $t->enum('subject_type',['public','pairwise'])->default('public'); $t->string('sector_identifier',253)->nullable(); $t->json('allowed_claims')->nullable(); $t->string('backchannel_logout_uri',2048)->nullable(); $t->enum('status',['active','disabled'])->default('active'); $t->timestamps(); $t->softDeletes(); $t->unique(['tenant_id','id']); $t->unique(['tenant_id','application_id','name']); });
    $create('scope', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->string('name',100); $t->string('description')->default(''); $t->json('claims')->nullable(); $t->smallInteger('is_builtin')->default(0); $t->smallInteger('status')->default(1); $t->timestamps(); $t->softDeletes(); $t->unique(['tenant_id','id']); $t->unique(['tenant_id','name']); });
    $create('client_secret', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('client_id'); $t->string('secret_prefix',16); $t->string('secret_hash'); foreach (['expires_at','revoked_at','last_used_at'] as $name) $t->dateTime($name)->nullable(); $t->timestamps(); $t->softDeletes(); $t->unique(['tenant_id','id']); $t->unique(['client_id','secret_prefix']); });
    $create('client_grant', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('client_id'); $t->enum('grant_type',['authorization_code','refresh_token','client_credentials']); $t->timestamps(); $t->softDeletes(); $t->unique(['tenant_id','client_id','grant_type']); });
