    $create('redirect_uri', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('client_id'); $t->string('uri',2048); $t->char('uri_hash',64); $t->timestamps(); $t->softDeletes(); $t->unique(['tenant_id','client_id','uri_hash']); });
    $create('oauth_authorization', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('client_id'); $t->bigInteger('user_id')->nullable(); $t->char('transaction_hash',64)->unique(); $t->string('redirect_uri',2048); $t->char('redirect_uri_hash',64); $t->string('response_type',32)->default('code'); $t->text('scope_names'); $t->text('state')->nullable(); $t->string('nonce')->nullable(); $t->string('code_challenge',128); $t->string('code_challenge_method',16)->default('S256'); $t->enum('subject_type',['user'])->default('user'); $t->enum('status',['pending','approved','denied','completed','expired','revoked'])->default('pending'); $t->dateTime('auth_time')->nullable(); $t->string('session_id',128)->nullable(); $t->bigInteger('oidc_session_id')->nullable(); $t->bigInteger('client_session_id')->nullable(); $t->dateTime('expires_at'); $t->dateTime('decided_at')->nullable(); $t->dateTime('interaction_consumed_at')->nullable(); $t->timestamps(); $t->unique(['tenant_id','id']); });
    $create('oauth_authorization_code', static function (Blueprint $t): void { $t->id(); foreach (['tenant_id','authorization_id','client_id','user_id'] as $name) $t->bigInteger($name); $t->string('code_prefix',16); $t->char('code_hash',64)->unique(); $t->char('redirect_uri_hash',64); $t->string('code_challenge',128); $t->string('nonce')->nullable(); $t->enum('subject_type',['user'])->default('user'); $t->dateTime('expires_at'); $t->dateTime('consumed_at')->nullable(); $t->dateTime('revoked_at')->nullable(); $t->timestamps(); $t->unique(['tenant_id','id']); });
    $create('oauth_token', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('client_id'); $t->bigInteger('user_id')->nullable(); $t->enum('token_type',['access','refresh']); $t->string('token_prefix',16); $t->char('token_hash',64)->unique(); $t->char('family_id',36)->nullable(); $t->bigInteger('parent_id')->nullable(); $t->integer('generation')->default(0); $t->enum('subject_type',['user','client']); $t->bigInteger('authorization_id')->nullable(); $t->string('session_id',128)->nullable(); $t->bigInteger('password_version')->nullable(); $t->bigInteger('session_version')->nullable(); $t->dateTime('expires_at'); $t->dateTime('consumed_at')->nullable(); $t->dateTime('revoked_at')->nullable(); $t->timestamps(); $t->unique(['tenant_id','id']); $t->index(['tenant_id','family_id','generation','revoked_at']); $t->index(['token_hash','token_type','revoked_at','expires_at']); });
    foreach (['oauth_authorization_scope' => 'authorization_id','oauth_token_scope' => 'token_id'] as $name => $owner) $create($name, static function (Blueprint $t) use ($owner): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger($owner); $t->bigInteger('scope_id'); $t->timestamps(); $t->unique(['tenant_id',$owner,'scope_id']); });
    $create('identity_consent', static function (Blueprint $t): void { $t->id(); $t->bigInteger('tenant_id'); $t->bigInteger('user_id'); $t->bigInteger('client_id'); $t->char('granted_scope_hash',64); $t->text('scope_names'); $t->dateTime('granted_at'); $t->dateTime('revoked_at')->nullable(); $t->timestamps(); $t->unique(['tenant_id','user_id','client_id','granted_scope_hash']); });
