    if (!Db::table('identity_tenant')->where('id',1)->exists()) Db::table('identity_tenant')->insert(['id'=>1,'public_id'=>'00000000-0000-4000-8000-000000000001','code'=>'default','name'=>'默认租户','status'=>1]);
    foreach (['openid'=>['sub'],'profile'=>['name','preferred_username','picture','locale'],'email'=>['email','email_verified'],'offline_access'=>[]] as $name=>$claims) Db::table('scope')->insertOrIgnore(['tenant_id'=>1,'name'=>$name,'description'=>$name,'claims'=>json_encode($claims),'is_builtin'=>1,'status'=>1]);
